mapper.sql:
SELECT knowledge_base_id FROM knowledge_base_member
WHERE tenant_id = #{tenantId} AND user_id = #{userId}

    UNION
    SELECT knowledge_base_id FROM knowledge_base_role_grant
    WHERE tenant_id = #{tenantId}
      AND role_id IN #{roleId}

mapper.select:
WITH relaxed AS MATERIALIZED (
    SELECT id, embedding <=> CAST(#{vector} AS vector) AS distance FROM chunk
    WHERE tenant_id = #{tenantId}
      AND knowledge_base_id IN ()

        AND knowledge_base_id IN #{kb}

      AND document_id IN ()
      AND embedding IS NOT NULL
    ORDER BY distance
    LIMIT #{limit}
)
SELECT id FROM relaxed ORDER BY distance + 0

SELECT id FROM chunk
WHERE tenant_id = #{tenantId}
  AND knowledge_base_id IN ()

    AND knowledge_base_id IN #{kb}

  AND document_id IN ()
  AND content ||| #{text}
ORDER BY pdb.score(id) DESC
LIMIT #{limit}

SELECT c.id AS chunk_id, c.document_id, d.filename AS document_name, c.heading_path, c.content
FROM chunk c JOIN document d ON d.id = c.document_id
WHERE c.tenant_id = #{tenantId}
  AND c.id IN #{id}

SELECT id AS chunk_id, content FROM chunk
WHERE tenant_id = #{tenantId}
  AND knowledge_base_id IN ()
  AND id IN #{id}
